"""specs_s200037.py - Sonnet-w2 family N (generated by mkfamN.py). 0x4cbe80 (ctor of the stack-local L, ecx=L as a stack marker) fills the first 0x60 bytes; 0x4cc1e0 (this+0x123, a, &L) and
0x4cbec0 read L back; the /GS check is a recorder preserving eax. Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _gen(c):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    sr1, sr2, sr3 = seh_record(c, 2), seh_record(c, 2), seh_record(c, 2)

    def fill(emu, k):
        emu.wbytes(emu.reg('ecx'), bytes(r.getrandbits(8) for _ in range(0x60)))
        sr1(emu, k)

    def mid_side(emu, k):
        emu.calllog.append(('L1', emu.rbytes(emu.arg32(1), 16).hex()))
        sr2(emu, k)

    def dtor_side(emu, k):
        emu.calllog.append(('L2', emu.rbytes(emu.reg('ecx'), 16).hex()))
        sr3(emu, k)
    hook_rec(c, 0x4cbe80, 1, ret=r.getrandbits(32), pop=4, this='mark', side=fill)
    hook_rec(c, 0x4cc1e0, 2, ret=r.getrandbits(32), pop=8, this=True, stackmark=(1,), side=mid_side)
    hook_rec(c, 0x4cbec0, 0, ret=r.getrandbits(32), this='mark', side=dtor_side)
    hook_rec(c, 0x633654, 0, ret=lambda emu, k: emu.reg('eax'), pop=0, this=True)
    return [rnd(c, 0x140), r.getrandbits(32)]


S(0x42d960, 'GUESS famN 0x42d960', 'thiscall', None, ret='eax', gen=_gen, note='batch200037')
S(0x42d9f0, 'GUESS famN 0x42d9f0', 'thiscall', None, ret='eax', gen=_gen, note='batch200037')
S(0x42fba0, 'GUESS famN 0x42fba0', 'thiscall', None, ret='eax', gen=_gen, note='batch200037')
S(0x42fe20, 'GUESS famN 0x42fe20', 'thiscall', None, ret='eax', gen=_gen, note='batch200037')
